window.senvaAssistant = {"items":[{"id":"faq0","q":"What is biological age?","a":"It’s an estimate of how old your body seems, based on markers such as epigenetic marks, compared with your age in years. If it’s lower than your age in years, your body shows fewer signs of ageing than expected.","links":[{"href":"science.html","label":"How epigenetic clocks work"}],"kw":["biological age","bio age","biologisk ålder","biological","biologisk","epigenetic age","how old is my body","how old am i","real age","true age","~age","~ålder","~older","~younger","~ageing","~aging"]},{"id":"faq1","q":"What will my report show?","a":"Your biological age, how fast you are ageing, and clear next steps on nutrition, movement and sleep. When you test again, it also shows your trend.","links":[],"kw":["report","rapport","result","resultat","pace","next steps","what do i get","what will i get","~show","~trend"]},{"id":"faq4","q":"Is Senva Health a medical test?","a":"No. Senva Health is a wellness test that helps you understand how you are ageing and what to work on. It doesn’t diagnose disease. If you have health concerns, talk to your doctor.","links":[],"kw":["medical","medicinsk","diagnose","diagnosis","diagnos","doctor","läkare","ivdr","ce mark","certified","approved","~disease","~sjukdom","~clinic"]},{"id":"faq6","q":"Do you read my genes?","a":"No. We don’t look at your genetic variants, and we don’t report on your ancestry or your inherited risk of disease. We measure epigenetic marks: small chemical tags on your DNA that shift with age and with how you live.","links":[],"kw":["gene","genetic","genetisk","gener","ancestry","genome","variant","inherited","hereditary","arv","dna"]},{"id":"faq7","q":"Why saliva and not blood?","a":"Saliva is easy to give at home, with no needles, and it carries DNA from your own cells. That’s why we designed Senva Health around it.","links":[],"kw":["saliva","saliv","spit","spott","blood","blod","needle","nål","finger prick","swab"]},{"id":"faq8","q":"How do you know it works?","a":"We’re testing the test before launch, with repeat saliva samples from volunteers.","links":[{"href":"about.html#validation","label":"More about this work"}],"kw":["accurate","accuracy","reliable","reliability","validated","validation","evidence","proof","proven","precise","precision","how do you know","is it accurate","really work","actually work","legit","scam","noggrann","tillförlitlig","~study","~trust"]},{"id":"faq9","q":"Is my data safe?","a":"Yes. Your sample is analysed in a European lab, and your results are kept safe in Europe under the EU’s data protection rules (GDPR). We never sell your data. Sign-ups to our waiting list go through Formspree, a form service in the USA.","links":[{"href":"privacy.html#who-else","label":"How we handle your sign-up"}],"kw":["data","privacy","private","gdpr","safe","secure","security","stored","storage","sell","third party","integritet","säker","säkra","säkert","dataskydd","personuppgifter","~europe","~share"]},{"id":"faq11","q":"Can I delete my data?","a":"Yes. Ask us at any time and we’ll delete it.","links":[],"kw":["delete","deletion","erase","remove my data","radera","ta bort","forget me"]},{"id":"faq12","q":"How often should I test?","a":"Testing again shows your trend over time. We’ll suggest when to retest when we launch.","links":[],"kw":["how often","often","retest","again","repeat","frequency","second test","hur ofta","igen"]},{"id":"faq13","q":"When can I order?","a":"We plan to launch in the EU in 2027. Join the waiting list and we’ll tell you first.","links":[{"href":"#waiting-list","label":"Join the waiting list"}],"kw":["order","buy","purchase","available","availability","launch","release","country","countries","ship","shipping","deliver","delivery","beställa","köpa","lansering","lanseras","lansera","leverans","~when","~när","~sweden"]},{"id":"price","q":"What will it cost?","a":"We haven’t announced the price yet. Join the waiting list and we’ll tell you before anyone else.","links":[{"href":"#waiting-list","label":"Join the waiting list"}],"kw":["price","cost","how much does","how much is","how much will","how much would","expensive","cheap","pay","payment","subscription","pris","kostar","kostnad","kr","sek","euro","eur"],"contact":false},{"id":"kit","q":"What’s in the kit?","a":"Senva Health is our at-home saliva kit. It arrives in one box, with a tube and a funnel for your sample. Give your sample, close the tube and post it back to the lab.","links":[{"href":"#kit","label":"See the kit"}],"kw":["kit","box","tube","funnel","package","parcel","contents","what is in","paket","låda","rör","tratt"],"contact":false},{"id":"how","q":"How does it work?","a":"Order online and a saliva kit arrives at your home. Give your sample in about five minutes, with no needles, and post it back. A European lab measures the marks on your DNA, and our model interprets them. You get clear next steps on nutrition, movement and sleep, and you can test again to follow your trend.","links":[{"href":"#how-it-works","label":"How it works"}],"kw":["how does it work","how it works","process","steps","take the sample","instructions","collect","post it","send it back","return","hur fungerar","fungerar det","~sample","~prov"],"contact":false},{"id":"different","q":"What makes Senva Health different?","a":"It runs on our own model of epigenetic ageing, developed at Umeå University. The model reads a small set of marks on your DNA, so we can explain what drives your result, not just give you a number. It’s built for saliva, so you can take the test at home, and your sample is analysed in a European lab.","links":[{"href":"#different","label":"What makes Senva Health different"}],"kw":["different","difference","other tests","compare","compared","comparison","competitor","competitors","unique","why senva","why choose","why should i","skillnad","skillnaden","skiljer","annorlunda","jämför","jämfört"],"contact":false},{"id":"turnaround","q":"How long until I get my result?","a":"We don’t have a turnaround time to share yet. If you’d like to know more, write to us.","links":[],"kw":["how long until","how long does it take","how long will it take","how long do i wait","turnaround","how many days","how many weeks","how fast","when will i get","when do i get","hur lång tid","svarstid"],"contact":true},{"id":"sample","q":"What happens to my sample?","a":"Before we offer the test, we’ll publish a separate privacy policy that explains how samples and results are handled. If you have a question now, write to us.","links":[{"href":"privacy.html","label":"Privacy notice"}],"kw":["what happens to my sample","what happens to my saliva","what happens to the sample","after the analysis","destroyed","destroy","biobank","keep my sample","store my sample","used for research","research use","sparas","förstörs"],"contact":true},{"id":"who","q":"Who is behind Senva?","a":"Senva is a spin-out from Umeå University, founded by Antón Carcedo (CTO) and Åke Brännström (CEO). We’re supported by the university’s Innovation Office and by Umeå University Holding through its Venture Track programme.","links":[{"href":"about.html","label":"About us"}],"kw":["founder","founders","team","company","behind","umeå","university","universitet","spin-out","spinout","startup","grundare","företag","about senva","based","located","where are you","where is senva","~who","~vem"],"contact":false},{"id":"partners","q":"I’m an investor or a possible partner","a":"Senva is at the pre-seed stage, funded through Umeå University Holding’s Venture Track programme. We’d like to hear from investors, labs and wellness companies, and organisations interested in a pilot around our launch in 2027. Write to Åke Brännström, CEO.","links":[{"href":"about.html#investors","label":"For investors and partners"},{"href":"mailto:ake.brannstrom@umu.se","label":"Email Åke"}],"kw":["invest","investor","investment","funding","partner","partnership","pilot","collaborate","collaboration","gym","press","journalist","media","business","investera","samarbete"],"contact":false},{"id":"science","q":"How does your model work?","a":"Epigenetic clocks estimate biological age from DNA methylation, small chemical tags on your DNA. Our own model was developed at Umeå University and is built for saliva. We don’t share the details of how it’s built, but our science page explains how epigenetic clocks work, with links to the research.","links":[{"href":"science.html","label":"How epigenetic clocks work"}],"kw":["model","algorithm","clock","epigenetic clock","methylation","metylering","science","research","machine learning","artificial intelligence","cpg","modell","vetenskap","forskning","calculate","epigenetic","epigenetik","ai"],"contact":false},{"id":"join","q":"How do I join the waiting list?","a":"Leave your email in a waiting-list form and tick the box. We’ll email you before Senva Health launches, and you can unsubscribe at any time.","links":[{"href":"#waiting-list","label":"Go to the waiting list"}],"kw":["waiting list","waitlist","sign up","signup","join","newsletter","notify","updates","väntelista","anmäl","nyhetsbrev"],"contact":false},{"id":"unsubscribe","q":"How do I unsubscribe?","a":"Use the unsubscribe link in any of our emails, or write to us and we’ll remove you.","links":[{"href":"privacy.html","label":"Privacy notice"}],"kw":["unsubscribe","stop emails","opt out","remove me","avregistrera","avsluta"],"contact":true},{"id":"limits","q":"Can it tell me about disease or how long I’ll live?","a":"No. An epigenetic age is an estimate, not a diagnosis. It says something about how your body is ageing on average, not whether you have or will get a particular disease. If you have health concerns, talk to your doctor.","links":[{"href":"science.html#limits","label":"What a clock can’t tell you"}],"kw":["lifespan","live longer","how long will i live","how long i will live","how long i live","longevity","life expectancy","die","death","predict","cancer","dementia","alzheimer","heart disease","livslängd","~risk"],"contact":false},{"id":"whocan","q":"Who can take the test?","a":"We’ll say who can take the test, including the minimum age, before we launch. If you’d like to ask whether it suits you, write to us.","links":[],"kw":["who can take","who can use","who is it for","who is the test for","can anyone","how old do i have to be","old enough","minimum age","age limit","under 18","child","children","kid","kids","teenager","barn","åldersgräns","vem kan"],"contact":true},{"id":"health","q":"I’m pregnant, on medication or have a health condition","a":"Senva Health is a wellness test and doesn’t diagnose disease. If you have health concerns, talk to your doctor. For questions about whether the test suits you, write to us.","links":[],"kw":["pregnant","pregnancy","gravid","medication","medicine","medicin","diabetes","illness","condition","treatment","chemotherapy","smoker","smoking","smoke"],"contact":true},{"id":"contact","q":"Write to us","a":"Write to us and one of us will reply by email.","links":[],"kw":["contact","email","e-mail","talk to","human","person","someone","support","phone","call","kontakt","kontakta","mejl","mail","~help","~hjälp"],"contact":true}],"start":["faq0","how","faq1","faq9","faq13","price"],"contacts":[{"name":"Antón Carcedo","role":"CTO","topics":"the test and the science","email":"anton.carcedo@umu.se"},{"name":"Åke Brännström","role":"CEO","topics":"investors, partners and press","email":"ake.brannstrom@umu.se"}]};
